// La conversación sobrevive a "Ocultar": al cerrar la ventana la tablet tira
// el JS del plugin y con él la memoria (se vio en un Manta con la 0.5.0).
//
// Dónde guardarla, descartado:
// - un archivo: el SDK no escribe archivos (FileUtils sólo copia, renombra,
//   borra, lista y crea carpetas);
// - la Files API de Anthropic: lo que sube el plugin no se puede volver a
//   bajar ("Only files generated by a tool … can be downloaded").
// Lo que queda: los NOMBRES de carpetas. El JSON va en base64url, cortado en
// pedazos, cada uno el nombre de una carpeta vacía, numerada, dentro del
// directorio privado del plugin (que no pide permisos). Se escribe en
// "memoria-nueva" y recién al final se cambia por "memoria": si la tablet corta
// a la mitad, queda la anterior entera.
//
// Para que entre, quien guarda deja afuera lo pesado (la foto del lazo y los
// dibujos se vuelven a traer al recuperar: ver conversacion.js).

const PEDAZO = 240; // caracteres por nombre (+ 6 del número: el límite de ext4/f2fs es 255 bytes)
const EN_PARALELO = 40; // carpetas creadas a la vez: de a una, guardar tardaba y se ocultaba antes

// fs: {makeDir, listFiles, deleteDir, renameToFile, dir}. En la tablet es el
// FileUtils de sn-plugin-lib; en la compu, uno sobre node:fs (scripts/probar-memoria.mjs).
export function crearMemoria(fs) {
  const viva = `${fs.dir}/memoria`;
  const nueva = `${fs.dir}/memoria-nueva`;
  let cola = Promise.resolve();
  let proximo = null; // lo último que pidieron guardar y todavía no se escribió

  async function escribir(datos) {
    const texto = aBase64Url(aUtf8(JSON.stringify(datos)));
    await fs.deleteDir(nueva).catch(() => null);
    await fs.makeDir(nueva);
    const nombres = [];
    for (let i = 0, n = 0; i < texto.length; i += PEDAZO, n++) {
      nombres.push(`${nueva}/${String(n).padStart(5, '0')}-${texto.slice(i, i + PEDAZO)}`);
    }
    for (let i = 0; i < nombres.length; i += EN_PARALELO) {
      const hechos = await Promise.all(nombres.slice(i, i + EN_PARALELO).map(p => fs.makeDir(p)));
      if (hechos.some(ok => !ok)) {
        throw new Error('no pude crear una carpeta de la memoria');
      }
    }
    await fs.deleteDir(viva).catch(() => null);
    if (!(await fs.renameToFile(nueva, viva))) {
      throw new Error('no pude cambiar la memoria por la nueva');
    }
  }

  return {
    // Si llegan varios mientras se escribe uno, sólo se escribe el último: lo
    // viejo (por ejemplo "pregunta pendiente") no tiene que demorar lo nuevo.
    guardar(datos) {
      const hayEnCola = proximo !== null;
      proximo = {version: 1, guardado: new Date().toISOString(), ...datos};
      if (!hayEnCola) {
        cola = cola
          .then(() => {
            const d = proximo;
            proximo = null;
            return escribir(d);
          })
          .catch(e => console.warn('[superclaude] no pude guardar la conversación', e));
      }
      return cola;
    },

    async recuperar() {
      await cola;
      let lista;
      try {
        lista = await fs.listFiles(viva);
      } catch {
        return null; // no hay memoria
      }
      const nombres = (lista || [])
        .map(f => String(f.path || f).split('/').pop())
        .filter(n => /^\d{5}-/.test(n))
        .sort();
      if (nombres.length === 0) {
        return null;
      }
      const texto = nombres.map(n => n.slice(6)).join('');
      return JSON.parse(deUtf8(deBase64Url(texto)));
    },

    olvidar() {
      cola = cola.then(() => fs.deleteDir(viva)).catch(() => null);
      return cola;
    },
  };
}

// UTF-8 y base64url a mano: no se sabe qué trae el Hermes de la tablet
// (TextEncoder, btoa), y esto es poco.
function aUtf8(s) {
  const b = [];
  for (const ch of s) {
    let c = ch.codePointAt(0);
    if (c < 0x80) {
      b.push(c);
    } else if (c < 0x800) {
      b.push(0xc0 | (c >> 6), 0x80 | (c & 63));
    } else if (c < 0x10000) {
      b.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    } else {
      b.push(0xf0 | (c >> 18), 0x80 | ((c >> 12) & 63), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63));
    }
  }
  return b;
}

function deUtf8(b) {
  let s = '';
  for (let i = 0; i < b.length; ) {
    const c = b[i++];
    let cp;
    if (c < 0x80) {
      cp = c;
    } else if (c < 0xe0) {
      cp = ((c & 31) << 6) | (b[i++] & 63);
    } else if (c < 0xf0) {
      cp = ((c & 15) << 12) | ((b[i++] & 63) << 6) | (b[i++] & 63);
    } else {
      cp = ((c & 7) << 18) | ((b[i++] & 63) << 12) | ((b[i++] & 63) << 6) | (b[i++] & 63);
    }
    s += String.fromCodePoint(cp);
  }
  return s;
}

const ABC = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';

function aBase64Url(b) {
  let s = '';
  for (let i = 0; i < b.length; i += 3) {
    const n = (b[i] << 16) | ((b[i + 1] ?? 0) << 8) | (b[i + 2] ?? 0);
    s += ABC[(n >> 18) & 63] + ABC[(n >> 12) & 63];
    s += i + 1 < b.length ? ABC[(n >> 6) & 63] : '';
    s += i + 2 < b.length ? ABC[n & 63] : '';
  }
  return s;
}

function deBase64Url(s) {
  const b = [];
  for (let i = 0; i < s.length; i += 4) {
    const v = [0, 1, 2, 3].map(k => (i + k < s.length ? ABC.indexOf(s[i + k]) : 0));
    const n = (v[0] << 18) | (v[1] << 12) | (v[2] << 6) | v[3];
    b.push((n >> 16) & 255);
    if (i + 2 < s.length) {
      b.push((n >> 8) & 255);
    }
    if (i + 3 < s.length) {
      b.push(n & 255);
    }
  }
  return b;
}
